SELECT status, count(*) AS row_count
FROM exception_queue_{topic_id}
WHERE consumer_group_id = {group_id}
GROUP BY status;

SELECT
	message_id,
	attempts,
	last_error,
	updated_at
FROM exception_queue_{topic_id}
WHERE consumer_group_id = {group_id}
	AND status = 'dead'
ORDER BY message_id;

SELECT
	message_id,
	status,
	attempts,
	updated_at
FROM exception_queue_{topic_id}
WHERE consumer_group_id = {group_id}
ORDER BY updated_at DESC
LIMIT 20;

